package com.happybananas.tracezilla;import com.fasterxml.jackson.databind.*;import com.happybananas.tracezilla.shopify.ShopifyClient;import com.happybananas.tracezilla.workflow.SynchronizeInventory;import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;
public final class InventoryServices{private InventoryServices(){}public static final class Shopify implements SynchronizeInventory.Writer{private final ShopifyClient client;private static final String QUERY="query GetInventoryItems($first:Int!,$after:String,$locationId:ID!){productVariants(first:$first,after:$after){nodes{sku inventoryItem{id tracked inventoryLevel(locationId:$locationId){quantities(names:[\"available\"]){name quantity}}}}pageInfo{hasNextPage endCursor}}}";private static final String MUTATION="mutation SetInventoryQuantity($input:InventorySetQuantitiesInput!){inventorySetQuantities(input:$input){userErrors{message}}}";public Shopify(ShopifyClient c){client=c;}public Map<String,SynchronizeInventory.Target> read(String location)throws Exception{var result=new HashMap<String,SynchronizeInventory.Target>();String after=null;do{var variables=new HashMap<String,Object>();variables.put("first",250);variables.put("after",after);variables.put("locationId",location);var connection=client.graphql(QUERY,variables).path("data").path("productVariants");for(var node:connection.path("nodes")){var sku=node.path("sku").asText("").trim();if(sku.isEmpty())continue;var item=node.path("inventoryItem");var level=item.path("inventoryLevel");Integer available=null;for(var q:level.path("quantities"))if(q.path("name").asText().equals("available"))available=q.path("quantity").asInt();result.put(sku,new SynchronizeInventory.Target(sku,item.path("id").asText(),item.path("tracked").asBoolean(),available));}if(!connection.path("pageInfo").path("hasNextPage").asBoolean())break;after=connection.path("pageInfo").path("endCursor").asText("");if(after.isBlank())throw new IllegalStateException("Shopify inventory pagination is missing a cursor.");}while(true);return result;}public void write(SynchronizeInventory.Target item,int quantity,String location)throws Exception{var q=new LinkedHashMap<String,Object>();q.put("inventoryItemId",item.inventoryItemId());q.put("locationId",location);q.put("quantity",quantity);q.put("compareQuantity",item.available());var input=new LinkedHashMap<String,Object>();input.put("name","available");input.put("reason","correction");input.put("referenceDocumentUri","tracezilla://inventory-sync/"+item.sku());input.put("quantities",List.of(q));var errors=client.graphql(MUTATION,Map.of("input",input)).path("data").path("inventorySetQuantities").path("userErrors");if(!errors.isEmpty())throw new IllegalStateException(errors.get(0).path("message").asText("Shopify rejected the update."));}}
public static final class Tracezilla implements SynchronizeInventory.Reader{private final Configuration config;private final HttpClient http;private final ObjectMapper json=new ObjectMapper();public Tracezilla(Configuration c){config=c;http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(c.timeout())).build();}public List<SynchronizeInventory.Source> read(int warehouse)throws Exception{var location=get("location-by-number/"+warehouse,Map.of()).path("data");if(!location.has("id"))throw new IllegalStateException("tracezilla warehouse response is missing an ID.");var query=new HashMap<String,String>();query.put("partner_location[eq]",location.path("id").asText());query.put("include","sku");query.put("perPage","250");var result=new ArrayList<SynchronizeInventory.Source>();do{var payload=get("inventory",query);for(var record:payload.path("data")){var sku=record.path("sku");var code=record.has("sku_code")?record.path("sku_code").asText():sku.path("sku_code").asText();result.add(new SynchronizeInventory.Source(code.trim(),record.path("traceable_quantity_available").asDouble(),record.path("none_traceable_quantity_available").asDouble(),sku.path("default_uom_conversion").asDouble(1),sku.path("none_traceable_uom_conversion").asDouble(1)));}var next=payload.path("links").path("next_page").asText("");if(next.isBlank())break;for(var pair:new URI(next).getRawQuery().split("&")){var p=pair.split("=",2);query.put(dec(p[0]),dec(p.length>1?p[1]:""));}}while(true);return result;}private JsonNode get(String path,Map<String,String> query)throws Exception{var qs=String.join("&",query.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).toList());var uri=URI.create(config.tracezillaUrl()+"/api/v1/"+config.teamSlug()+"/"+path+(qs.isEmpty()?"":"?"+qs));var request=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(config.timeout())).header("Accept","application/json").header("Authorization","Bearer "+config.apiKey()).GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new IllegalStateException("tracezilla request failed with HTTP "+response.statusCode()+".");return json.readTree(response.body());}private static String enc(String v){return URLEncoder.encode(v,java.nio.charset.StandardCharsets.UTF_8);}private static String dec(String v){return URLDecoder.decode(v,java.nio.charset.StandardCharsets.UTF_8);}}}
